/* solver_qpsol:(h[119x119,99nz],g[119],a[120x119,408nz],lba[120],uba[120],lbx[119],ubx[119],x0[119],lam_x0[119],lam_a0[120],q[0x119],p[])->(x[119],cost,lam_a[120],lam_x[119]) */
static int casadi_f3(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  OSQPWorkspace *work=casadi_f3_mem[mem];
  casadi_int i, n, offset;
  /* Set objective */
  if (arg[1]) {
    casadi_copy(arg[1], 119, w);
  } else {
    casadi_clear(w, 119);
  }
  if (osqp_update_lin_cost(work, w)) return 1;
  /* Set bounds */
  if (arg[5]) {
    casadi_copy(arg[5], 119, w);
  } else {
    casadi_fill(w, 119, -casadi_inf);
  }
  if (arg[3]) {
    casadi_copy(arg[3], 120, w+119);
  } else {
    casadi_fill(w+119, 120, -casadi_inf);
  }
  if (arg[6]) {
    casadi_copy(arg[6], 119, w+239);
  } else {
    casadi_fill(w+239, 119, casadi_inf);
  }
  if (arg[4]) {
    casadi_copy(arg[4], 120, w+358);
  } else {
    casadi_fill(w+358, 120, casadi_inf);
  }
  if (osqp_update_bounds(work, w, w+239)) return 1;
  /* Project Hessian */
  casadi_tri_project(arg[0], casadi_s1, w, 0);/* Get constraint matrix */
  offset = 0;
  for (i=0; i< 119; ++i) {
    w[99+offset] = 1;
    offset++;
    n = casadi_s15[i+1]-casadi_s15[i];
    casadi_copy(arg[2]+casadi_s15[i], n, w+offset+99);
    offset+= n;
  }
  /* Pass Hessian and constraint matrices */
  if (osqp_update_P_A(work, w, 0, 99, w+99, 0, 527)) return 1;
  if (osqp_warm_start_x(work, arg[7])) return 1;
  if (arg[8]) {
    casadi_copy(arg[8], 119, w);
  } else {
    casadi_clear(w, 119);
  }
  if (arg[9]) {
    casadi_copy(arg[9], 120, w+119);
  } else {
    casadi_clear(w+119, 120);
  }
  if (osqp_warm_start_y(work, w)) return 1;
  if (osqp_solve(work)) return 1;
  if (res[1]) casadi_copy(&work->info->obj_val, 1, res[1]);
  if (res[0]) casadi_copy(work->solution->x, 119, res[0]);
  if (res[3]) casadi_copy(work->solution->y, 119, res[3]);
  if (res[2]) casadi_copy(work->solution->y+119, 120, res[2]);
  if (work->info->status_val != OSQP_SOLVED) {
    return -1000;
  }
  return 0;
  return 0;
}

void casadi_f3_incref(void) {
}

void casadi_f3_decref(void) {
}

int casadi_f3_alloc_mem(void) {
  return casadi_f3_mem_counter++;
}

int casadi_f3_init_mem(int mem) {
  OSQPData data;
  OSQPSettings settings;
  c_int A_colind[120], A_row[527], H_colind[120], H_row[99], i;
  casadi_real dummy[527];
  csc A, H;
  casadi_clear(dummy, 527);
  for (i=0;i<527;++i) A_row[i] = casadi_s16[i];
  for (i=0;i<120;++i) A_colind[i] = casadi_s17[i];
  for (i=0;i<99;++i) H_row[i] = casadi_s0[i];
  for (i=0;i<120;++i) H_colind[i] = casadi_s18[i];
  A.m = 239;
  A.n = 119;
  A.nz = 527;
  A.nzmax = 527;
  A.x = dummy;
  A.i = A_row;
  A.p = A_colind;
  H.m = 119;
  H.n = 119;
  H.nz = 99;
  H.nzmax = 99;
  H.x = dummy;
  H.i = H_row;
  H.p = H_colind;
  data.n = 119;
  data.m = 239;
  data.P = &H;
  data.q = dummy;
  data.A = &A;
  data.l = dummy;
  data.u = dummy;
  osqp_set_default_settings(&settings);
  settings.rho = 0.1;
  settings.sigma = 1e-06;
  settings.scaling = 10;
  settings.adaptive_rho = 1;
  settings.adaptive_rho_interval = 0;
  settings.adaptive_rho_tolerance = 5;
  settings.max_iter = 4000;
  settings.eps_abs = 0.001;
  settings.eps_rel = 0.001;
  settings.eps_prim_inf = 0.0001;
  settings.eps_dual_inf = 0.0001;
  settings.alpha = 1.6;
  settings.delta = 1e-06;
  settings.polish = 0;
  settings.polish_refine_iter = 3;
  settings.verbose = 0;
  settings.scaled_termination = 0;
  settings.check_termination = 25;
  settings.warm_start = 0;
  return osqp_setup(&casadi_f3_mem[mem], &data, &settings)!=0;
}

void casadi_f3_free_mem(int mem) {
  osqp_cleanup(casadi_f3_mem[mem]);
}

int casadi_f3_checkout(void) {
  int mid;
  if (casadi_f3_unused_stack_counter>=0) {
    return casadi_f3_unused_stack[casadi_f3_unused_stack_counter--];
  } else {
    if (casadi_f3_mem_counter==CASADI_MAX_NUM_THREADS) return -1;
    mid = casadi_f3_alloc_mem();
    if (mid<0) return -1;
    if(casadi_f3_init_mem(mid)) return -1;
    return mid;
  }
}

void casadi_f3_release(int mem) {
  casadi_f3_unused_stack[++casadi_f3_unused_stack_counter] = mem;
}

